-- StudentNest Backend Stage 3 — Properties & Listings
-- Run this AFTER Stage 1 and Stage 2 migrations against the existing studentnest database.

SET @c = (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='properties' AND COLUMN_NAME='state');
SET @sql = IF(@c=0, 'ALTER TABLE properties ADD COLUMN state VARCHAR(100) NULL AFTER city', 'SELECT 1'); PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;
SET @c = (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='properties' AND COLUMN_NAME='postal_code');
SET @sql = IF(@c=0, 'ALTER TABLE properties ADD COLUMN postal_code VARCHAR(20) NULL AFTER state', 'SELECT 1'); PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;
SET @c = (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='properties' AND COLUMN_NAME='property_subtype');
SET @sql = IF(@c=0, 'ALTER TABLE properties ADD COLUMN property_subtype VARCHAR(80) NULL AFTER property_type', 'SELECT 1'); PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;
SET @c = (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='properties' AND COLUMN_NAME='service_charge');
SET @sql = IF(@c=0, 'ALTER TABLE properties ADD COLUMN service_charge DECIMAL(12,2) NOT NULL DEFAULT 0 AFTER rent', 'SELECT 1'); PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;
SET @c = (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='properties' AND COLUMN_NAME='agent_fee');
SET @sql = IF(@c=0, 'ALTER TABLE properties ADD COLUMN agent_fee DECIMAL(12,2) NOT NULL DEFAULT 0 AFTER service_charge', 'SELECT 1'); PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;
SET @c = (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='properties' AND COLUMN_NAME='security_deposit');
SET @sql = IF(@c=0, 'ALTER TABLE properties ADD COLUMN security_deposit DECIMAL(12,2) NOT NULL DEFAULT 0 AFTER agent_fee', 'SELECT 1'); PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;
SET @c = (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='properties' AND COLUMN_NAME='total_cost');
SET @sql = IF(@c=0, 'ALTER TABLE properties ADD COLUMN total_cost DECIMAL(12,2) NOT NULL DEFAULT 0 AFTER security_deposit', 'SELECT 1'); PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;
SET @c = (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='properties' AND COLUMN_NAME='amenities');
SET @sql = IF(@c=0, 'ALTER TABLE properties ADD COLUMN amenities JSON NULL AFTER bathrooms', 'SELECT 1'); PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;
SET @c = (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='properties' AND COLUMN_NAME='images');
SET @sql = IF(@c=0, 'ALTER TABLE properties ADD COLUMN images JSON NULL AFTER amenities', 'SELECT 1'); PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;
SET @c = (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='properties' AND COLUMN_NAME='rejection_reason');
SET @sql = IF(@c=0, 'ALTER TABLE properties ADD COLUMN rejection_reason VARCHAR(500) NULL AFTER listing_status', 'SELECT 1'); PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;
SET @c = (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='properties' AND COLUMN_NAME='submitted_at');
SET @sql = IF(@c=0, 'ALTER TABLE properties ADD COLUMN submitted_at DATETIME NULL AFTER rejection_reason', 'SELECT 1'); PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;
SET @c = (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='properties' AND COLUMN_NAME='approved_at');
SET @sql = IF(@c=0, 'ALTER TABLE properties ADD COLUMN approved_at DATETIME NULL AFTER submitted_at', 'SELECT 1'); PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;

CREATE INDEX IF NOT EXISTS idx_properties_provider_status ON properties(provider_id, listing_status);
CREATE INDEX IF NOT EXISTS idx_properties_browse ON properties(city, area, property_type, availability_status, listing_status);
